mapper.update:
UPDATE tb_feed_task SET status='RUNNING',lease_owner=#{owner},lease_until=#{leaseUntil}
WHERE id=#{task.id} AND cursor_id=#{task.cursorId} AND attempts=#{task.attempts}
  AND ((status='PENDING' AND next_attempt <= #{now}) OR (status='RUNNING' AND lease_until <= #{now}))

UPDATE tb_feed_task SET status=#{status},last_error=#{reason,jdbcType=VARCHAR},
  lease_owner=NULL,lease_until=NULL,finished_at=#{now}
WHERE id=#{taskId} AND lease_owner=#{owner} AND status='RUNNING'
